                // the palette's Esc is handled here.
                if let Some(palette) = &this.palette
                    && palette.read(cx).is_open(window, cx)
                {
                    palette.update(cx, |palette, cx| palette.cancel(window, cx));
                    return;
                }
                // Likewise any other dialog, such as the quit confirmation.
                if window.has_active_dialog(cx) {
                    window.close_dialog(cx);
                    return;
                }
                this.prompt_mode
                    .update(cx, |prompt_mode, cx| prompt_mode.focus_chat(window, cx))
            }))
            .on_action(
                cx.listener(|this, _: &TogglePalette, window, cx| this.toggle_palette(window, cx)),
            )
            .on_action(cx.listener(|this, _: &Quit, window, cx| this.quit(window, cx)))
            .child(self.toolbar.clone())
            .child(
                div().flex_1().min_h_0().child(
                    // One `children` call for every panel: the group's
                    // `children` replaces panels added before it.
                    h_resizable("sidebar-split")
                        .with_state(&self.sidebar_split)
                        .children([
                            resizable_panel()
                                .size(SIDEBAR_WIDTH)
                                .size_range(MIN_SIDEBAR_WIDTH..Pixels::MAX)
                                .child(self.sidebar.clone()),
                            resizable_panel()
                                .size_range(MIN_SPLIT_WIDTH..Pixels::MAX)
                                .child(self.prompt_mode.clone()),
                        ]),
                ),
            )
            // Inside the window's element tree, so actions such as
            // TogglePalette reach it from a focused dialog.
        })
        .detach();
    }
}

impl Render for Toolbar {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let project = ProjectDirectory::get(cx);
        let project_label: SharedString = project
            .as_ref()
            .and_then(|dir| dir.file_name())
            .map(|name| name.to_string_lossy().into_owned().into())
            .unwrap_or_else(|| "Open Project…".into());
        let project_tooltip: SharedString = project
            .as_ref()
            .map(|dir| dir.display().to_string().into())
            .unwrap_or_else(|| "Select a piton.config.pi file".into());

        let side = || {
            div()
                .flex_1()
                .min_w_0()
                .flex()
                .flex_row()
                .items_center()
                .gap_2()
        };

        div()
            .flex()
            .flex_row()
            .items_center()
            .gap_2()
            .px_3()
            .py_2()
            .border_b_1()
            .border_color(cx.theme().border)
            .child(
                side()
                    .child(
                        Button::new("project-directory")
                            .ghost()
                            .label(project_label)
                            .tooltip(project_tooltip)
                            .on_click(
                                cx.listener(|this, _, window, cx| this.pick_project(window, cx)),
                            ),
                    )
                    .child(
                        Button::new("build")
                            .primary()
                            .label("Build")
                            .tooltip("Run piton build")
                            .loading(self.building)
                            .disabled(project.is_none() || self.building)
                            .on_click(cx.listener(|this, _, window, cx| this.build(window, cx))),
                    ),
            )
            .child(
                side().justify_end().child(
                    gpui_kit::component::switch::Switch::new("dark-mode")
                        .label("Dark mode")
                        .checked(cx.theme().is_dark())
                        .on_click(|dark, window, cx| set_dark_mode(*dark, window, cx)),
                ),
            )
    }
}

/// Switches between light and dark mode, saving the choice.
pub fn set_dark_mode(dark: bool, window: &mut Window, cx: &mut App) {
    let mode = if dark {
        gpui_kit::component::ThemeMode::Dark
    } else {
        gpui_kit::component::ThemeMode::Light
    };
    if let Err(err) = theme_preference::set(mode, window, cx) {
        let note = Notification::error(format!("{err:#}")).title("Could not save dark mode");
        window.push_notification(note, cx);
    }
}
